345	                      }
346	                    }
347	                  }
348	                }
349	              }
350	            },
351	            {
352	              "if": {
353	                "properties": {
354	                  "scheduled_reconciliation": {
355	                    "properties": {
356	                      "enabled": {
357	                        "const": true
358	                      }
359	                    }
360	                  }
361	                }
362	              },
363	              "then": {
364	                "properties": {
365	                  "local_reconciliation": {
366	                    "contains": {
367	                      "const": "scheduled_sync"
368	                    }
369	                  }
370	                }
371	              }
372	            }
